#[test]
fn v2_shared_binary_wire_vectors() {
    assert_eq!(
        sha256(V2_CROSS_LANGUAGE_VECTORS.as_bytes()),
        "7D0B45134943BF5DA768BEF4617A9294F17F56571E218F8401CE6AC0C66CD283"
    );
    use base64::{Engine as _, engine::general_purpose::STANDARD};
    let vectors: Vec<serde_json::Value> = serde_json::from_str(V2_CROSS_LANGUAGE_VECTORS).unwrap();
    assert_eq!(vectors.len(), 51);
    for vector in vectors {
        let bytes = STANDARD
            .decode(vector["canonicalBytesBase64"].as_str().unwrap())
            .unwrap();
        assert_eq!(
            parse_binding(&bytes).is_ok(),
            vector["accepted"].as_bool().unwrap(),
            "v2 shared vector {}",
            vector["name"]
        );
    }
}

