#[path = "../src/bin/phase3-prestart-v1.rs"]
pub mod prestart;
use prestart::*;

pub fn sample(root: &str) -> StartupBinding {
    let file = |path: String| FileBinding {
        path,
        bytes: 17,
        sha256: "A".repeat(64),
    };
    StartupBinding {
        schema: SCHEMA.into(),
        acceptance_id: "11111111-1111-4111-8111-111111111111".into(),
        accepted_generation: AcceptedGeneration {
            p: GitTuple {
                commit: "1".repeat(40),
                tree: "2".repeat(40),
                parent: ACCEPTED_C1.into(),
            },
            a: GitTuple {
                commit: "3".repeat(40),
                tree: "4".repeat(40),
                parent: "1".repeat(40),
            },
            k: CarrierTuple {
                commit: "5".repeat(40),
                tree: "6".repeat(40),
                parent: "3".repeat(40),
                carrier_blob_id: "7".repeat(40),
            },
        },
        repository_root: root.into(),
        cwd: root.into(),
        native_prestart: file(format!(r"{root}\bin\phase3-prestart-v1.exe")),
        node: NodeBinding {
            path: format!(r"{root}\bin\node.exe"),
            bytes: 17,
            sha256: "A".repeat(64),
            version: "v24.15.0".into(),
            platform: "win32".into(),
            arch: "x64".into(),
        },
        live_entry: file(format!(
            r"{root}\packages\rm0032-phase3-runner\src\phase3-hardening-live-entry.mjs"
        )),
        carrier: file(format!(
            r"{root}\project\verification\rm-0032-phase3-live-hardening-carrier.json"
        )),
        launcher: file(format!(
            r"{root}\bin\rm0032-phase3-native-observer-launcher-v1.exe"
        )),
        observer: file(format!(r"{root}\bin\rm0032-phase3-native-observer-v1.exe")),
        binary_bindings: BinaryBindings {
            runner: file(format!(r"{root}\bin\runner.exe")),
            git: file(FIXED_GIT.into()),
            wsl: file(FIXED_WSL.into()),
        },
    }
}

#[test]
fn direct_git_engine_binding_refuses_wrapper_and_other_engines() {
    let good = sample(r"D:\Accepted\Repository");
    assert_eq!(good.binary_bindings.git.path, r"C:\Program Files\Git\mingw64\bin\git.exe");
    assert!(parse_binding(&canonical_bytes(&good)).is_ok());
    for path in [
        r"C:\Program Files\Git\cmd\git.exe",
        r"C:\Program Files\Git\bin\git.exe",
        r"C:\Program Files\Git\mingw64\bin\other.exe",
    ] {
        let mut hostile = good.clone();
        hostile.binary_bindings.git.path = path.into();
        assert_ne!(canonical_bytes(&hostile), canonical_bytes(&good));
        assert!(parse_binding(&canonical_bytes(&hostile)).is_err());
    }
}

#[test]
fn direct_wsl_engine_binding_refuses_shim_and_other_engines() {
    let good = sample(r"D:\Accepted\Repository");
    assert_eq!(good.binary_bindings.wsl.path, r"C:\Program Files\WSL\wsl.exe");
    assert!(parse_binding(&canonical_bytes(&good)).is_ok());
    for path in [
        r"C:\Windows\System32\wsl.exe",
        r"C:\Windows\SysWOW64\wsl.exe",
        r"C:\Program Files\WSL\wslservice.exe",
        r"C:\Program Files\WSL\other.exe",
        r"C:\Program Files\WSL-other\wsl.exe",
        r"C:\Program Files\WSL\WSL.exe",
    ] {
        let mut hostile = good.clone();
        hostile.binary_bindings.wsl.path = path.into();
        assert_ne!(canonical_bytes(&hostile), canonical_bytes(&good));
        assert!(parse_binding(&canonical_bytes(&hostile)).is_err());
    }
}

#[cfg(windows)]
#[test]
fn direct_wsl_engine_has_only_exact_vendor_ancestors() {
    use prestart::native_startup_files::{fixed_external_policy, AclPolicy};
    let directory = r"C:\Program Files\WSL";
    assert!(matches!(fixed_external_policy(directory, true), Some(AclPolicy::FixedWsl)));
    assert!(fixed_external_policy(directory, false).is_none());
    assert!(matches!(fixed_external_policy(FIXED_WSL, false), Some(AclPolicy::FixedWsl)));
    assert!(fixed_external_policy(FIXED_WSL, true).is_none());
    assert!(matches!(fixed_external_policy(r"C:\Program Files", true), Some(AclPolicy::FixedWindows)));
    for path in [
        r"C:\Windows\System32\wsl.exe",
        r"C:\Windows\SysWOW64\wsl.exe",
        r"C:\Program Files\WSL\wslservice.exe",
        r"C:\Program Files\WSL\other.exe",
        r"C:\Program Files\WSL\bin",
        r"C:\Program Files\WSL-other",
        r"C:\Program Files\wsl",
        r"C:\Program Files\WSL\WSL.exe",
    ] {
        assert!(fixed_external_policy(path, false).is_none());
        assert!(fixed_external_policy(path, true).is_none());
    }
}

#[cfg(windows)]
#[test]
fn direct_git_engine_has_only_exact_vendor_ancestors() {
    use prestart::native_startup_files::{fixed_external_policy, AclPolicy};
    for path in [
        r"C:\Program Files\Git",
        r"C:\Program Files\Git\mingw64",
        r"C:\Program Files\Git\mingw64\bin",
    ] {
        assert!(matches!(fixed_external_policy(path, true), Some(AclPolicy::FixedGit)));
        assert!(fixed_external_policy(path, false).is_none());
    }
    assert!(matches!(fixed_external_policy(FIXED_GIT, false), Some(AclPolicy::FixedGit)));
    assert!(fixed_external_policy(FIXED_GIT, true).is_none());
    for path in [
        r"C:\Program Files\Git\cmd",
        r"C:\Program Files\Git\cmd\git.exe",
        r"C:\Program Files\Git\mingw64\bin\other.exe",
        r"C:\Program Files\Git\mingw64\libexec",
        r"C:\Program Files\Git\mingw64-other\bin",
    ] {
        assert!(fixed_external_policy(path, false).is_none());
        assert!(fixed_external_policy(path, true).is_none());
    }
}

#[test]
fn closed_wire_vectors() {
    let good = sample(r"D:\Accepted\Repository");
    let bytes = canonical_bytes(&good);
    assert_eq!(canonical_bytes(&parse_binding(&bytes).unwrap()), bytes);
    assert!(parse_binding(&[&bytes[..], b"\n"].concat()).is_err());
    assert!(parse_binding(&[&[0xef, 0xbb, 0xbf][..], &bytes].concat()).is_err());
    assert!(parse_binding(&vec![b'x'; MAX_BINDING_BYTES + 1]).is_err());
    let mut value = serde_json::to_value(&good).unwrap();
    value["ownerSid"] = "S-1-1-0".into();
    assert!(parse_binding(&serde_json::to_vec(&value).unwrap()).is_err());
    let duplicate =
        String::from_utf8(bytes.clone())
            .unwrap()
            .replacen("{", "{\"schema\":\"duplicate\",", 1);
    assert!(parse_binding(duplicate.as_bytes()).is_err());
    for mutation in 0..16 {
        let mut binding = good.clone();
        match mutation {
            0 => binding.node.sha256 = "a".repeat(64),
            1 => binding.node.bytes = 0,
            2 => binding.node.bytes = MAX_SAFE_INTEGER + 1,
            3 => binding.node.version = "v24.14.0".into(),
            4 => binding.cwd.push_str(r"\different"),
            5 => binding.live_entry.path.push_str(".poison"),
            6 => binding.carrier.path.push_str(".poison"),
            7 => binding.accepted_generation.k.parent = "8".repeat(40),
            8 => binding.accepted_generation.a.parent = "8".repeat(40),
            9 => binding.accepted_generation.p.parent = "8".repeat(40),
            10 => binding.accepted_generation.k.carrier_blob_id = "A".repeat(40),
            11 => binding.acceptance_id = "11111111-1111-1111-8111-111111111111".into(),
            12 => binding.native_prestart.path = r"d:\Accepted\Repository\bin\other.exe".into(),
            13 => binding.node.path = r"D:\Accepted\..\node.exe".into(),
            14 => binding.observer.path = binding.launcher.path.clone(),
            15 => binding.schema.push_str(".old"),
            _ => unreachable!(),
        }
        assert!(
            parse_binding(&canonical_bytes(&binding)).is_err(),
            "mutation {mutation}"
        );
    }
    #[cfg(windows)]
    {
        assert_eq!(
            native::command_line(&good),
            "\"D:\\Accepted\\Repository\\bin\\node.exe\" \"D:\\Accepted\\Repository\\packages\\rm0032-phase3-runner\\src\\phase3-hardening-live-entry.mjs\""
        );
        assert_eq!(
            String::from_utf16(&native::environment()).unwrap(),
            "SystemRoot=C:\\Windows\0WINDIR=C:\\Windows\0\0"
        );
    }
}

#[test]
fn no_caller_control_or_git_before_node() {
    let source = include_str!("../src/bin/phase3-prestart-v1.rs");
    assert!(source.contains("prepare_at(BINDING_PATH, own_path)"));
    assert!(source.contains("std::env::args_os().count() != 1"));
    for forbidden in [
        "std::process::Command",
        "GetEnvironmentVariable",
        "NODE_OPTIONS=",
        "fd3",
        "CreateProcessAsUserW(",
    ] {
        assert!(
            !source.contains(forbidden),
            "unexpected prestart surface: {forbidden}"
        );
    }
}

#[test]
fn hostile_scalar_types_are_not_coerced() {
    let good = serde_json::to_value(sample(r"D:\Accepted\Repository")).unwrap();
    for pointer in [
        "/schema",
        "/acceptanceId",
        "/repositoryRoot",
        "/cwd",
        "/node/path",
        "/node/sha256",
        "/node/version",
        "/node/platform",
        "/node/arch",
        "/nativePrestart/sha256",
        "/carrier/sha256",
        "/binaryBindings/runner/path",
        "/binaryBindings/git/sha256",
        "/binaryBindings/wsl/path",
        "/acceptedGeneration/p/commit",
        "/acceptedGeneration/a/tree",
        "/acceptedGeneration/k/carrierBlobId",
    ] {
        for hostile in [
            serde_json::json!([good.pointer(pointer).unwrap()]),
            serde_json::json!(null),
            serde_json::json!(42),
            serde_json::json!({}),
        ] {
            let mut changed = good.clone();
            *changed.pointer_mut(pointer).unwrap() = hostile;
            assert!(
                parse_binding(&serde_json::to_vec(&changed).unwrap()).is_err(),
                "wrong type {pointer}"
            );
        }
    }
    for hostile in [
        serde_json::json!("17"),
        serde_json::json!([17]),
        serde_json::json!(17.5),
        serde_json::json!(-1),
    ] {
        let mut changed = good.clone();
        changed["node"]["bytes"] = hostile;
        assert!(parse_binding(&serde_json::to_vec(&changed).unwrap()).is_err());
    }
}
